insert into ged.label_template_design_field(template_design_id,field_key,field_label,field_type,x_mm,y_mm,width_mm,height_mm,font_size_pt,is_required,display_order)
select t.id,f.field_key,f.field_label,f.field_type,f.x,f.y,f.w,f.h,f.fs,f.required,f.ord from templates t join fields f using(template_code) on conflict do nothing;
